package com.nexabuilder;

import org.springframework.boot.SpringApplication;
import org.springframework.boot.autoconfigure.SpringBootApplication;
import org.springframework.cache.annotation.EnableCaching;
import org.springframework.context.annotation.Bean;
import org.springframework.scheduling.TaskScheduler;
import org.springframework.scheduling.annotation.EnableAsync;
import org.springframework.scheduling.annotation.EnableScheduling;
import org.springframework.scheduling.concurrent.ThreadPoolTaskScheduler;

@SpringBootApplication
@EnableCaching
@EnableAsync
@EnableScheduling
public class NexaBuilderApplication {

    public static void main(String[] args) {
        SpringApplication.run(NexaBuilderApplication.class, args);
    }

    /**
     * TaskScheduler used by {@link com.nexabuilder.core.schedule.ScheduledJobManager}
     * to fire cron-driven jobs. Spring Boot would auto-provide one, but
     * the default size (1) starves under more than a couple of jobs;
     * 4 covers the typical metadata-app workload without forking off
     * thread pools the operator can't see.
     */
    @Bean
    public TaskScheduler taskScheduler() {
        ThreadPoolTaskScheduler scheduler = new ThreadPoolTaskScheduler();
        scheduler.setPoolSize(4);
        scheduler.setThreadNamePrefix("nexa-sched-");
        scheduler.setWaitForTasksToCompleteOnShutdown(true);
        scheduler.setAwaitTerminationSeconds(20);
        return scheduler;
    }
}
